  SELECT q.id, 'B', 'process_step_confusion', $q$contradicted by an explicit control result$q$ FROM q
  UNION ALL SELECT q.id, 'C', 'partial_truth', $q$correct under a different condition, namely if the muscle had been injured$q$ FROM q
